from solution import cycpattern_check
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference_model(a, b):
    """Obviously-correct model directly from spec: True iff any rotation of b is substring of a."""
    if b == "":
        # empty word is a substring of every word
        return True
    for i in range(len(b)):
        if (b[i:] + b[:i]) in a:
            return True
    return False


def rotate(s, k):
    if len(s) == 0:
        return s
    k = k % len(s)
    return s[k:] + s[:k]


@pytest.mark.parametrize(
    "a,b,expected",
    [
        ("abcd", "abd", False),
        ("hello", "ell", True),
        ("whassup", "psus", False),
        ("abab", "baa", True),
        ("efef", "eeff", False),
        ("himenss", "simen", True),
    ],
)
def test_spec_examples(a, b, expected):
    assert cycpattern_check(a, b) is expected


def test_empty_pattern_is_always_found():
    # empty word is a substring of any word, so any rotation check must be True
    assert cycpattern_check("abcd", "") is True
    assert cycpattern_check("hello", "") is True
    assert cycpattern_check("", "") is True
    assert cycpattern_check("x", "") is True


def test_both_empty_pattern():
    assert cycpattern_check("", "") is True


def test_empty_text_with_nonempty_pattern_is_false():
    assert cycpattern_check("", "a") is False
    assert cycpattern_check("", "abc") is False


@given(
    a=st.text(alphabet="ab", min_size=0, max_size=8),
    b=st.text(alphabet="ab", min_size=0, max_size=5),
)
def test_equivalence_to_reference_model(a, b):
    assert cycpattern_check(a, b) == reference_model(a, b)


@given(
    a=st.text(alphabet="abc", min_size=0, max_size=10),
    b=st.text(alphabet="abc", min_size=1, max_size=5),
    k=st.integers(min_value=0, max_value=10),
)
def test_rotation_invariance(a, b, k):
    # set of rotations of b equals set of rotations of any rotation of b
    r = rotate(b, k)
    assert cycpattern_check(a, b) == cycpattern_check(a, r)


@given(
    a=st.text(alphabet="abc", min_size=0, max_size=10),
    b=st.text(alphabet="abc", min_size=0, max_size=5),
)
def test_substring_implies_match(a, b):
    # rotation by 0 is b itself, so if b is substring of a, must return True
    assume b in a
    assert cycpattern_check(a, b) is True


@given(
    a=st.text(alphabet="abc", min_size=0, max_size=6),
    b=st.text(alphabet="abc", min_size=0, max_size=4),
    k=st.integers(min_value=0, max_value=8),
)
def test_exact_rotation_present_implies_match(a, b, k):
    # embed a rotation of b into a; result must be True
    assume len(b) > 0
    r = rotate(b, k)
    assume len(r) <= 4
    pos = st.integers(min_value=0, max_value=len(a)).example() if False else 0
    # deterministic embedding: insert in middle
    mid = len(a) // 2
    a2 = a[:mid] + r + a[mid:]
    assume len(a2) <= 12
    assert cycpattern_check(a2, b) is True


@given(
    a=st.text(alphabet="abc", min_size=0, max_size=6),
    b=st.text(alphabet="abc", min_size=1, max_size=8),
)
def test_longer_pattern_cannot_match(a, b):
    assume len(b) > len(a)
    assert cycpattern_check(a, b) is False


@given(
    a=st.text(alphabet="abc", min_size=0, max_size=8),
    b=st.text(alphabet="abc", min_size=0, max_size=5),
    extra=st.text(alphabet="abc", min_size=0, max_size=5),
)
def test_extending_text_preserves_match(a, b, extra):
    # if a rotation of b is in a, it is still in a+extra and extra+a
    assume cycpattern_check(a, b) is True
    assert cycpattern_check(a + extra, b) is True
    assert cycpattern_check(extra + a, b) is True


@given(b=st.text(alphabet="abc", min_size=0, max_size=6))
def test_word_matches_itself_and_rotations(b):
    # b is always a rotation-substring of itself
    assert cycpattern_check(b, b) is True
    if len(b) > 0:
        for i in range(len(b)):
            assert cycpattern_check(rotate(b, i), b) is True
            assert cycpattern_check(b, rotate(b, i)) is True


def test_single_character_cases():
    assert cycpattern_check("a", "a") is True
    assert cycpattern_check("abc", "b") is True
    assert cycpattern_check("abc", "d") is False
    assert cycpattern_check("abab", "a") is True
